# ---- 2026-10-27 全量核验：只覆盖“的、每”；“不”由素材库 cross 修复 ----
def _qa_de():
    child = lib.kid(310, 446, s=0.92, arms="point", point_at=(470, 340), look=(6, 2))
    ball = lib.ball(478, 360, 50, main=lib.RED, dark=lib.RED_D, hi=lib.PINK)
    ring = '<ellipse cx="474" cy="358" rx="86" ry="76" fill="none" stroke="#f2b53c" stroke-width="6" stroke-dasharray="3 14" stroke-linecap="round"/>'
    return lib.ground() + child + ring + ball


def _qa_mei_cup(cx):
    return lib.wrap(
        lib.R(cx - 41, 316, 82, 108, 12, lib.RED_D),
        lib.R(cx - 47, 310, 82, 108, 12, lib.RED),
        lib.E(cx - 6, 310, 41, 9, lib.RED_D),
        lib.E(cx - 6, 310, 31, 6, "#f2916c"),
        lib.R(cx - 33, 326, 10, 72, 5, lib.WHITE, 0.55),
    )


def _qa_mei():
    cups = "".join(_qa_mei_cup(cx) for cx in (214, 384, 554))
    marks = "".join(lib.check(cx - 6, 250, 26, lib.TEAL, 8) for cx in (214, 384, 554))
    return lib.ground() + cups + marks


_arts_before_qa = arts


def arts():
    result = dict(_arts_before_qa())
    result.update({"的": _qa_de(), "每": _qa_mei()})
    return result
